/**
 * The Brand Builder (§13–§19).
 *
 * One question at a time, with a way out of every one of them.
 *
 * The identity it produces is not a mock-up. `derivePalette`, `deriveTypography`
 * and `buildLogoBrief` are imported from the compiled brand engine — the same
 * modules the server runs — so the palette a founder sees here is exactly the
 * palette in the brand kit they download. That is the reason this file is an ES
 * module while the rest of the front end is a plain script.
 *
 * The written strategy (name, promise, story) is generated by a language model
 * and therefore needs a server route with the API key. Rather than fake it, this
 * page says so plainly and shows the brief that would be sent.
 */

import { derivePalette, deriveTypography, buildLogoBrief } from './generated/identity.js';

const STORAGE_KEY = 'brandora.brief';

const state = {
  questions: [],
  index: 0,
  answers: {},
  helpOpen: false,
  variation: 0,
};

const el = {
  progress: document.querySelector('[data-progress]'),
  question: document.querySelector('[data-question]'),
  result: document.querySelector('[data-result]'),
};

/* --- Persistence ---------------------------------------------------------- */

/**
 * Answers survive a refresh.
 *
 * A founder filling this in on a phone on mobile data will lose the tab. Losing
 * seven considered answers with it is the difference between coming back and
 * not, and §15 exists precisely because these questions are hard to answer once.
 */
function save() {
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state.answers));
  } catch (err) {
    // Storage unavailable; the interview still works within this page view.
  }
}

function restore() {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw) state.answers = JSON.parse(raw);
  } catch (err) {
    state.answers = {};
  }
}

/* --- Rendering ------------------------------------------------------------ */

function t(key, fallback, vars) {
  const translated = window.brandoraTranslate ? window.brandoraTranslate(key, vars) : null;
  return translated === null || translated === undefined ? fallback : translated;
}

function renderProgress() {
  el.progress.innerHTML = '';
  state.questions.forEach((question, i) => {
    const seg = document.createElement('div');
    seg.className = 'progress__seg';
    seg.setAttribute('data-done', String(i <= state.index));
    el.progress.appendChild(seg);
  });
  el.progress.setAttribute(
    'aria-label',
    'Question ' + (state.index + 1) + ' of ' + state.questions.length,
  );
}

function currentAnswer() {
  const question = state.questions[state.index];
  return state.answers[question.field];
}

function renderQuestion() {
  const question = state.questions[state.index];
  if (!question) return renderResult();

  renderProgress();

  const answer = currentAnswer();
  const parts = [];

  parts.push('<p class="eyebrow">' + (state.index + 1) + ' / ' + state.questions.length + '</p>');
  parts.push('<h2>' + escapeHtml(question.prompt) + '</h2>');
  parts.push('<p class="field__why">' + escapeHtml(question.because) + '</p>');

  if (state.helpOpen) {
    parts.push('<div class="help-note">');
    parts.push('<p>' + escapeHtml(question.helpPrompt) + '</p>');
    if (question.examples && question.examples.length) {
      parts.push('<ul>');
      question.examples.forEach((example) => {
        parts.push('<li>' + escapeHtml(example) + '</li>');
      });
      parts.push('</ul>');
    }
    parts.push('</div>');
  }

  if (question.kind === 'text') {
    const value = typeof answer === 'string' ? answer : '';
    parts.push('<div class="field">');
    parts.push('<label for="answer">' + escapeHtml(question.prompt) + '</label>');
    parts.push(
      '<textarea id="answer" data-input>' + escapeHtml(value) + '</textarea>',
    );
    parts.push('</div>');
  } else if (question.kind === 'choice') {
    parts.push('<div class="field" role="group" aria-label="' + escapeHtml(question.prompt) + '">');
    question.options.forEach((option) => {
      const selected = answer === option.value;
      parts.push(
        '<button type="button" class="option" data-choice="' +
          escapeHtml(option.value) +
          '" aria-pressed="' +
          (selected ? 'true' : 'false') +
          '"><strong>' +
          escapeHtml(option.label) +
          '</strong><span class="option__hint">' +
          escapeHtml(option.hint) +
          '</span></button>',
      );
    });
    parts.push('</div>');
  } else {
    const selected = Array.isArray(answer) ? answer : [];
    parts.push('<div class="field chips" role="group" aria-label="' + escapeHtml(question.prompt) + '">');
    question.options.forEach((option) => {
      parts.push(
        '<button type="button" class="chip" data-multi="' +
          escapeHtml(option.value) +
          '" aria-pressed="' +
          (selected.indexOf(option.value) !== -1 ? 'true' : 'false') +
          '">' +
          escapeHtml(option.label) +
          '</button>',
      );
    });
    parts.push('</div>');
  }

  parts.push('<div class="hero__actions" style="margin-top:1rem">');
  if (state.index > 0) {
    parts.push('<button type="button" class="btn btn--ghost" data-back>' + t('builder.back', 'Back') + '</button>');
  }
  parts.push('<button type="button" class="btn btn--primary" data-next>' + t('builder.next', 'Continue') + '</button>');
  parts.push(
    '<button type="button" class="btn btn--quiet" data-help>' +
      t('builder.dontknow', "I don't know — help me") +
      '</button>',
  );
  parts.push('</div>');

  el.question.innerHTML = parts.join('');
  el.result.hidden = true;
  el.question.hidden = false;

  const input = el.question.querySelector('[data-input]');
  if (input) input.focus();
}

/* --- The identity --------------------------------------------------------- */

/** Shape the answers the way `@brandora/brand-engine` expects a brief. */
function toBrief() {
  const answers = state.answers;
  return {
    business: answers.business || '',
    product: answers.product || '',
    audience: answers.audience || '',
    positioning: answers.positioning || 'accessible-premium',
    personality: Array.isArray(answers.personality) ? answers.personality : [],
    differentiation: answers.differentiation || '',
    style: answers.style || '',
    inferredFields: state.inferred || [],
    locale: document.documentElement.getAttribute('lang') || 'en',
  };
}

function renderResult() {
  const brief = toBrief();
  const palette = derivePalette(brief, { variation: state.variation });
  const typography = deriveTypography(brief);

  // Until the AI has named the brand, the interview's own words stand in — a
  // placeholder that reads like the founder's business, not "Your Brand Here".
  const workingName = (brief.business.split(/[.,]/)[0] || 'Your brand').trim().slice(0, 40);
  const logoBrief = buildLogoBrief(brief, palette, typography, workingName);

  const swatches = palette
    .map(
      (swatch) =>
        '<li class="swatch"><div class="swatch__chip" style="background:' +
        swatch.hex +
        '"></div><div class="swatch__name">' +
        escapeHtml(swatch.name) +
        '</div><div class="swatch__hex">' +
        swatch.hex +
        '</div></li>',
    )
    .join('');

  const rationale = palette
    .map((swatch) => '<li><strong>' + escapeHtml(swatch.name) + '</strong> — ' + escapeHtml(swatch.rationale) + '</li>')
    .join('');

  el.result.innerHTML =
    '<h2>' + escapeHtml(workingName) + '</h2>' +
    '<p class="lede">' + escapeHtml(brief.product) + ' &middot; ' + escapeHtml(brief.positioning.replace('-', ' ')) + '</p>' +

    '<div class="card" style="margin-top:1.5rem">' +
      '<h3 data-i18n="brand.palette">Colour palette</h3>' +
      '<ul class="swatches">' + swatches + '</ul>' +
      '<ul style="padding-inline-start:1.1rem;color:var(--ink-muted);font-size:0.92rem">' + rationale + '</ul>' +
      '<p class="product__meta">Every palette Brandora generates is checked for contrast before you see it, so your text stays readable on a phone in daylight.</p>' +
    '</div>' +

    '<div class="card" style="margin-top:1rem">' +
      '<h3 data-i18n="brand.typography">Typography</h3>' +
      '<p style="font-size:1.6rem;margin-bottom:0.25rem;font-family:' + escapeHtml(typography.primary) + ',' + typography.primaryFallback + '">' +
        escapeHtml(workingName) +
      '</p>' +
      '<p class="product__meta">Headings: ' + escapeHtml(typography.primary) + ' &middot; Body: ' + escapeHtml(typography.secondary) + '</p>' +
      '<p>' + escapeHtml(typography.rationale) + '</p>' +
    '</div>' +

    '<div class="card" style="margin-top:1rem">' +
      '<h3 data-i18n="brand.logoBrief">Logo direction</h3>' +
      '<p>' + escapeHtml(logoBrief) + '</p>' +
    '</div>' +

    '<div class="notice" style="margin-top:1rem">' +
      'Your brand <strong>name, promise and story</strong> are written by Brandora AI, which runs on the server so the API key never reaches your browser. ' +
      'Connect the AI service to generate them — your answers are saved and nothing here is lost.' +
    '</div>' +

    '<div class="hero__actions">' +
      '<button type="button" class="btn btn--ghost" data-regenerate>' + t('builder.regenerate', 'Regenerate') + '</button>' +
      '<a class="btn btn--primary" href="catalog.html">' + t('nav.catalog', 'Catalogue') + '</a>' +
      '<button type="button" class="btn btn--quiet" data-restart>Start again</button>' +
    '</div>';

  // The rest of the site reads this to price and preview against the brand.
  try {
    localStorage.setItem(
      'brandora.identity',
      JSON.stringify({ name: workingName, palette: palette, typography: typography, brief: brief }),
    );
  } catch (err) {
    // The identity simply does not carry across pages this session.
  }

  el.question.hidden = true;
  el.result.hidden = false;
  el.result.focus();
}

/* --- Interaction ---------------------------------------------------------- */

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value).replace(/[&<>"']/g, (char) => {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char];
  });
}

function advance() {
  const question = state.questions[state.index];
  const answer = state.answers[question.field];

  const empty =
    answer === undefined ||
    (typeof answer === 'string' && answer.trim() === '') ||
    (Array.isArray(answer) && answer.length === 0);

  // A required question with no answer stops here rather than producing a brief
  // the engine would reject three screens later.
  if (question.required && empty) {
    const input = el.question.querySelector('[data-input]');
    if (input) {
      input.setAttribute('aria-invalid', 'true');
      input.focus();
    }
    state.helpOpen = true;
    renderQuestion();
    return;
  }

  state.helpOpen = false;
  state.index += 1;
  save();
  if (state.index >= state.questions.length) renderResult();
  else renderQuestion();
}

document.addEventListener('click', (event) => {
  const target = event.target.closest ? event.target : null;
  if (!target) return;
  const question = state.questions[state.index];

  const choice = target.closest('[data-choice]');
  if (choice && question) {
    state.answers[question.field] = choice.getAttribute('data-choice');
    save();
    renderQuestion();
    return;
  }

  const multi = target.closest('[data-multi]');
  if (multi && question) {
    const value = multi.getAttribute('data-multi');
    const current = Array.isArray(state.answers[question.field]) ? state.answers[question.field] : [];
    const at = current.indexOf(value);
    if (at === -1) current.push(value);
    else current.splice(at, 1);
    state.answers[question.field] = current;
    save();
    renderQuestion();
    return;
  }

  if (target.closest('[data-help]')) {
    state.helpOpen = !state.helpOpen;
    renderQuestion();
    return;
  }

  if (target.closest('[data-back]')) {
    state.index = Math.max(0, state.index - 1);
    state.helpOpen = false;
    renderQuestion();
    return;
  }

  if (target.closest('[data-next]')) {
    const input = el.question.querySelector('[data-input]');
    if (input && question) state.answers[question.field] = input.value;
    advance();
    return;
  }

  if (target.closest('[data-regenerate]')) {
    state.variation += 1;
    renderResult();
    return;
  }

  if (target.closest('[data-restart]')) {
    state.answers = {};
    state.index = 0;
    state.variation = 0;
    save();
    renderQuestion();
  }
});

/* --- Start ---------------------------------------------------------------- */

restore();

fetch('data/interview.json')
  .then((response) => response.json())
  .then((questions) => {
    state.questions = questions;
    renderQuestion();
  })
  .catch(() => {
    el.question.innerHTML =
      '<div class="notice">We could not load the interview just now. Please refresh the page.</div>';
  });
